Evaluate the JavaScript sorting algorithms visualizer implementation on a scale of 0-10 points:

**Algorithm Implementation (4 points)**: Does it correctly implement all five sorting algorithms (Bubble, Quick, Merge, Heap, Radix) with accurate logic and complexity analysis?

**Visualization Quality (3 points)**: Does it provide clear visual feedback with proper color coding, call stack visualization for recursive algorithms, and working area highlighting?

**Interactive Features (2 points)**: Does it include functional controls (algorithm selection, speed control, step/continuous modes, scramble patterns) and real-time statistics?

**Performance & Code Quality (1 point)**: Does it run smoothly at 60 FPS with well-structured, educational code?

Solution A: function initSortVisualizer(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    canvas.width = 500;
    canvas.height = 500;
    const ctx = canvas.getContext('2d');

    const N = 50;
    let arrData = [];
    let comparisons = 0;
    let swaps = 0;
    let recDepth = 0;
    let algorithm = 'Bubble';
    let speed = 5; // 1 (slow) to 10 (fast)
    let stepMode = false;
    let continuousTimer = null;
    let generator = null;

    // UI Elements
    const container = document.createElement('div');
    container.style.display = 'flex';
    container.style.flexDirection = 'column';
    container.style.alignItems = 'center';
    container.style.fontFamily = 'sans-serif';
    container.style.margin = '10px';

    const controls = document.createElement('div');
    controls.style.display = 'flex';
    controls.style.gap = '10px';
    controls.style.marginBottom = '10px';

    const algSelect = document.createElement('select');
    ['Bubble', 'Quick', 'Merge', 'Heap', 'Radix'].forEach(name => {
        const opt = document.createElement('option');
        opt.value = name;
        opt.text = name;
        algSelect.appendChild(opt);
    });
    controls.appendChild(algSelect);

    const speedLabel = document.createElement('label');
    speedLabel.textContent = 'Speed:';
    const speedSlider = document.createElement('input');
    speedSlider.type = 'range';
    speedSlider.min = '1';
    speedSlider.max = '10';
    speedSlider.value = speed.toString();
    speedLabel.appendChild(speedSlider);
    controls.appendChild(speedLabel);

    const stepToggle = document.createElement('label');
    stepToggle.textContent = 'Step-by-step';
    const stepCheckbox = document.createElement('input');
    stepCheckbox.type = 'checkbox';
    stepToggle.appendChild(stepCheckbox);
    controls.appendChild(stepToggle);

    const scramblePatternSelect = document.createElement('select');
    ['Random', 'Reverse', 'Nearly Sorted'].forEach(name => {
        const opt = document.createElement('option');
        opt.value = name;
        opt.text = name;
        scramblePatternSelect.appendChild(opt);
    });
    controls.appendChild(scramblePatternSelect);

    const scrambleButton = document.createElement('button');
    scrambleButton.textContent = 'Scramble';
    controls.appendChild(scrambleButton);

    const nextButton = document.createElement('button');
    nextButton.textContent = 'Next';
    nextButton.style.display = 'none';
    controls.appendChild(nextButton);

    const counterDiv = document.createElement('div');
    counterDiv.textContent = 'Comparisons: 0 Swaps: 0 Recursion Depth: 0 Complexity: O(n^2)';
    counterDiv.style.marginTop = '10px';

    container.appendChild(controls);
    container.appendChild(counterDiv);
    document.body.appendChild(container);

    function resetCounters() {
        comparisons = 0;
        swaps = 0;
        recDepth = 0;
    }

    function render() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const barWidth = canvas.width / N;
        const maxVal = Math.max(...arrData.map(d => d.value));
        arrData.forEach((d, i) => {
            const valRatio = d.value / maxVal;
            const barHeight = valRatio * canvas.height * 0.9;
            ctx.fillStyle = getColor(d.status);
            ctx.fillRect(i * barWidth, canvas.height - barHeight, barWidth - 2, barHeight);
        });
    }

    function getColor(status) {
        switch (status) {
            case 'compare': return 'red';
            case 'swap': return 'yellow';
            case 'sorted': return 'green';
            case 'pivot': return 'blue';
            case 'working': return '#d3d3d3';
            default: return 'white';
        }
    }

    function shuffle(array) {
        for (let i = array.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [array[i], array[j]] = [array[j], array[i]];
        }
    }

    function scramble(pattern) {
        if (pattern === 'Random') {
            arrData = arrData.map((_, i) => ({ value: i + 1, status: 'default' }));
            shuffle(arrData);
        } else if (pattern === 'Reverse') {
            arrData = arrData.map((_, i) => ({ value: N - i, status: 'default' }));
        } else if (pattern === 'Nearly Sorted') {
            arrData = arrData.map((_, i) => ({ value: i + 1, status: 'default' }));
            for (let i = 0; i < Math.floor(N / 10); i++) {
                const a = Math.floor(Math.random() * N);
                const b = Math.floor(Math.random() * N);
                [arrData[a], arrData[b]] = [arrData[b], arrData[a]];
            }
        }
        render();
    }

    function getComplexity(name) {
        const map = {
            Bubble: 'O(n²)',
            Quick: 'O(n log n) average, O(n²) worst',
            Merge: 'O(n log n)',
            Heap: 'O(n log n)',
            Radix: 'O(k n)'
        };
        return map[name] || '';
    }

    function advance() {
        if (!generator) return;
        const { done } = generator.next();
        render();
        counterDiv.textContent = `Comparisons: ${comparisons} Swaps: ${swaps} Recursion Depth: ${recDepth} Complexity: ${getComplexity(algorithm)}`;
        if (done) {
            arrData.forEach(d => d.status = 'sorted');
            render();
            if (continuousTimer) clearInterval(continuousTimer);
            continuousTimer = null;
        } else if (!stepMode && continuousTimer === null) {
            startContinuous();
        }
    }

    function startContinuous() {
        if (continuousTimer) clearInterval(continuousTimer);
        const delay = 1000 / (speed * 2);
        continuousTimer = setInterval(() => {
            advance();
        }, delay);
    }

    function stopContinuous() {
        if (continuousTimer) {
            clearInterval(continuousTimer);
            continuousTimer = null;
        }
    }

    // Sorting Algorithm Generators
    function* bubbleSort(data) {
        const n = data.length;
        for (let i = 0; i < n - 1; i++) {
            for (let j = 0; j < n - i - 1; j++) {
                data[j].status = 'compare';
                data[j + 1].status = 'compare';
                yield;
                comparisons++;
                if (data[j].value > data[j + 1].value) {
                    data[j].status = 'swap';
                    data[j + 1].status = 'swap';
                    yield;
                    swaps++;
                    [data[j].value, data[j + 1].value] = [data[j + 1].value, data[j].value];
                    yield;
                }
                data[j].status = 'default';
                data[j + 1].status = 'default';
            }
        }
    }

    function* quickSort(data, left, right) {
        if (left < right) {
            const pivotIdx = left + Math.floor((right - left) / 2);
            const pivotVal = data[pivotIdx].value;
            data[pivotIdx].status = 'pivot';
            yield;
            recDepth++;
            let i = left, j = right;
            while (i <= j) {
                while (data[i].value < pivotVal) {
                    data[i].status = 'compare';
                    yield;
                    comparisons++;
                    data[i].status = 'default';
                    i++;
                }
                while (data[j].value > pivotVal) {
                    data[j].status = 'compare';
                    yield;
                    comparisons++;
                    data[j].status = 'default';
                    j--;
                }
                if (i <= j) {
                    data[i].status = 'swap';
                    data[j].status = 'swap';
                    yield;
                    swaps++;
                    [data[i].value, data[j].value] = [data[j].value, data[i].value];
                    yield;
                    data[i].status = 'default';
                    data[j].status = 'default';
                    i++;
                    j--;
                }
            }
            data[pivotIdx].status = 'default';
            yield;
            recDepth--;
            yield* quickSort(data, left, j);
            yield* quickSort(data, i, right);
        }
    }

    function* mergeSort(data, left, right) {
        if (left < right) {
            const mid = Math.floor((left + right) / 2);
            yield* mergeSort(data, left, mid);
            yield* mergeSort(data, mid + 1, right);
            const leftArr = data.slice(left, mid + 1).map(d => ({ value: d.value }));
            const rightArr = data.slice(mid + 1, right + 1).map(d => ({ value: d.value }));
            let i = 0, j = 0, k = left;
            while (i < leftArr.length && j < rightArr.length) {
                leftArr[i].status = 'compare';
                rightArr[j].status = 'compare';
                yield;
                comparisons++;
                if (leftArr[i].value <= rightArr[j].value) {
                    data[k].value = leftArr[i].value;
                    data[k].status = 'swap';
                    yield;
                    swaps++;
                    data[k].status = 'default';
                    i++;
                } else {
                    data[k].value = rightArr[j].value;
                    data[k].status = 'swap';
                    yield;
                    swaps++;
                    data[k].status = 'default';
                    j++;
                }
                k++;
            }
            while (i < leftArr.length) {
                data[k].value = leftArr[i].value;
                data[k].status = 'swap';
                yield;
                swaps++;
                data[k].status = 'default';
                i++; k++;
            }
            while (j < rightArr.length) {
                data[k].value = rightArr[j].value;
                data[k].status = 'swap';
                yield;
                swaps++;
                data[k].status = 'default';
                j++; k++;
            }
        }
    }

    function* heapSort(data) {
        const n = data.length;
        const heapify = function (size, root) {
            let largest = root;
            const l = 2 * root + 1;
            const r = 2 * root + 2;
            if (l < size && data[l].value > data[largest].value) largest = l;
            if (r < size && data[r].value > data[largest].value) largest = r;
            if (largest !== root) {
                data[root].status = 'swap';
                data[largest].status = 'swap';
                yield;
                swaps++;
                [data[root].value, data[largest].value] = [data[largest].value, data[root].value];
                yield;
                data[root].status = 'default';
                data[largest].status = 'default';
                yield* heapify(size, largest);
            }
        };
        for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
            yield* heapify(n, i);
        }
        for (let i = n - 1; i > 0; i--) {
            data[0].status = 'swap';
            data[i].status = 'swap';
            yield;
            swaps++;
            [data[0].value, data[i].value] = [data[i].value, data[0].value];
            yield;
            data[0].status = 'default';
            data[i].status = 'default';
            yield* heapify(i, 0);
        }
    }

    function* radixSort(data) {
        const base = 10;
        const max = Math.max(...data.map(d => d.value));
        let exp = 1;
        while (Math.floor(max / exp) > 0) {
            const bucket = Array.from({ length: base }, () => []);
            for (let i = 0; i < data.length; i++) {
                data[i].status = 'compare';
                yield;
                comparisons++;
                const idx = Math.floor((data[i].value / exp) % base);
                bucket[idx].push({ value: data[i].value });
                data[i].status = 'default';
            }
            let index = 0;
            for (let i = 0; i < base; i++) {
                for (let j = 0; j < bucket[i].length; j++) {
                    data[index].value = bucket[i][j].value;
                    data[index].status = 'swap';
                    yield;
                    swaps++;
                    data[index].status = 'default';
                    index++;
                }
            }
            exp *= base;
        }
    }

    function getGenerator() {
        const data = arrData;
        if (algorithm === 'Bubble') return bubbleSort(data);
        if (algorithm === 'Quick') return quickSort(data, 0, data.length - 1);
        if (algorithm === 'Merge') return mergeSort(data, 0, data.length - 1);
        if (algorithm === 'Heap') return heapSort(data);
        if (algorithm === 'Radix') return radixSort(data);
    }

    function startSorting() {
        stopContinuous();
        resetCounters();
        generator = getGenerator();
        advancedId = null;
        advance();
    }

    // Event listeners
    scrambleButton.addEventListener('click', () => {
        scramble(scramblePatternSelect.value);
        startSorting();
    });

    algSelect.addEventListener('change', () => {
        algorithm = algSelect.value;
        counterDiv.textContent = `Comparisons: ${comparisons} Swaps: ${swaps} Recursion Depth: ${recDepth} Complexity: ${getComplexity(algorithm)}`;
    });

    speedSlider.addEventListener('input', (e) => {
        speed = parseInt(e.target.value, 10);
    });

    stepCheckbox.addEventListener('change', (e) => {
        stepMode = e.target.checked;
        nextButton.style.display = stepMode ? '' : 'none';
        if (stepMode) stopContinuous();
    });

    nextButton.addEventListener('click', () => {
        advance();
    });

    // Initial scramble and start
    scramble('Random');
    startSorting();
}

Solution B: function createSortingVisualizer(canvasId){const canvas=document.getElementById(canvasId);const ctx=canvas.getContext('2d');const width=canvas.width;const height=canvas.height;const barCount=100;let data=new Array(barCount);let colors=new Array(barCount).fill('gray');let compareSet=new Set();let swapSet=new Set();let sortedSet=new Set();let pivotIdx=null;let rangeStart=null,rangeEnd=null;let depth=0;let maxDepth=0;let compCount=0,swapCount=0;let speed=50;let continuous=true;let algorithm='Bubble';const algorithms={Bubble:{func:bubbleSort,complexity:'O(n²)'},Quick:{func:quickSort,complexity:'O(n log n)'},Merge:{func:mergeSort,complexity:'O(n log n)'},Heap:{func:heapSort,complexity:'O(n log n)'},Radix:{func:radixSort,complexity:'O(k·n)'}};function initData(){for(let i=0;i<barCount;i++)data[i]=i+1;}function shuffle(){for(let i=barCount-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[data[i],data[j]]=[data[j],data[i]];}}function reverse(){data=data.slice().reverse();}function nearlySorted(){shuffle();for(let i=0;i<10;i++){let a=Math.floor(Math.random()*barCount);let b=Math.floor(Math.random()*barCount);[data[a],data[b]]=[data[b],data[a]];}}function resetState(){colors.fill('gray');compareSet.clear();swapSet.clear();sortedSet.clear();pivotIdx=null;rangeStart=null;rangeEnd=null;depth=0;maxDepth=0;compCount=0;swapCount=0;}function draw(){ctx.clearRect(0,0,width,height);let barW=width/barCount;for(let i=0;i<barCount;i++){let h=data[i]/barCount*height;let x=i*barW;let y=height-h;let color=colors[i];if(compareSet.has(i))color='red';else if(swapSet.has(i))color='yellow';else if(sortedSet.has(i))color='green';else if(i===pivotIdx)color='blue';else if(rangeStart!==null&&i>=rangeStart&&i<=rangeEnd)color='lightblue';ctx.fillStyle=color;ctx.fillRect(x,y,barW-1,h);}ctx.fillStyle='black';ctx.font='14px sans-serif';ctx.fillText('Algorithm: '+algorithm+' ('+algorithms[algorithm].complexity+')',10,20);ctx.fillText('Comparisons: '+compCount,10,40);ctx.fillText('Swaps: '+swapCount,10,60);ctx.fillText('Depth: '+depth,10,80);}let animationId=null;function start(){if(animationId)cancelAnimationFrame(animationId);function step(){draw();animationId=requestAnimationFrame(step);}step();}function runGenerator(gen){function next(){let res=gen.next();if(res.done){sortedSet=new Set([...Array(barCount).keys()]);pivotIdx=null;rangeStart=null;rangeEnd=null;return;}let act=res.value;processAction(act);if(continuous){setTimeout(next,speed);}else{document.getElementById('nextBtn').disabled=false;}}next();}function processAction(act){compareSet.clear();swapSet.clear();pivotIdx=null;rangeStart=null;rangeEnd=null;switch(act.type){case'compare':compareSet.add(act.i);compareSet.add(act.j);compCount++;break;case'swap':[data[act.i],data[act.j]]=[data[act.j],data[act.i]];swapSet.add(act.i);swapSet.add(act.j);swapCount++;break;case'pivot':pivotIdx=act.i;break;case'range':rangeStart=act.start;rangeEnd=act.end;break;case'sorted':sortedSet.add(act.i);break;case'depth':depth=act.val;if(act.val>maxDepth)maxDepth=act.val;break;}}function* bubbleSort(arr){let n=arr.length;let swapped;do{swapped=false;for(let i=0;i<n-1;i++){yield{type:'compare',i,i+1};if(arr[i]>arr[i+1]){yield{type:'swap',i,i+1};[arr[i],arr[i+1]]=[arr[i+1],arr[i]];swapped=true;}}n--;for(let i=0;i<barCount;i++)if(i>=n)yield{type:'sorted',i};}while(swapped);}function* quickSort(arr,l=0,r=arr.length-1,dep=1){yield{type:'depth',val:dep};if(l<r){let p=yield* partition(arr,l,r,dep);yield{type:'range',start:l,end:r};yield* quickSort(arr,l,p-1,dep+1);yield* quickSort(arr,p+1,r,dep+1);}else if(l===r){yield{type:'sorted',i:l};}}function* partition(arr,l,r,dep){let pivot=arr[r];pivotIdx=r;yield{type:'pivot',i:r};let i=l-1;for(let j=l;j<r;j++){yield{type:'compare',i:j};if(arr[j]<=pivot){i++;yield{type:'swap',i,j};[arr[i],arr[j]]=[arr[j],arr[i]];}}yield{type:'swap',i+1,r};[arr[i+1],arr[r]]=[arr[r],arr[i+1]];yield{type:'sorted',i:i+1};return i+1;}function* mergeSort(arr,l=0,r=arr.length-1,dep=1){yield{type:'depth',val:dep};if(l<r){let m=Math.floor((l+r)/2);yield* mergeSort(arr,l,m,dep+1);yield* mergeSort(arr,m+1,r,dep+1);yield* merge(arr,l,m,r);}else if(l===r){yield{type:'sorted',i:l};}}function* merge(arr,l,m,r){let n1=m-l+1,n2=r-m;let L=arr.slice(l,m+1),R=arr.slice(m+1,r+1);let i=0,j=0,k=l;while(i<n1&&j<n2){yield{type:'compare',i:l+i,j:m+1+j};if(L[i]<=R[j]){arr[k]=L[i];yield{type:'sorted',i:k};i++;}else{arr[k]=R[j];yield{type:'sorted',i:k};j++;}k++;}while(i<n1){arr[k]=L[i];yield{type:'sorted',i:k};i++;k++;}while(j<n2){arr[k]=R[j];yield{type:'sorted',i:k};j++;k++;}}function* heapSort(arr){let n=arr.length;function* heapify(n,i){let largest=i;let l=2*i+1,r=2*i+2;if(l<n){yield{type:'compare',i:l,j:largest};if(arr[l]>arr[largest])largest=l;}if(r<n){yield{type:'compare',i:r,j:largest};if(arr[r]>arr[largest])largest=r;}if(largest!==i){yield{type:'swap',i,i:largest};[arr[i],arr[largest]]=[arr[largest],arr[i]];yield* heapify(n,largest);} }for(let i=Math.floor(n/2)-1;i>=0;i--)yield* heapify(n,i);for(let i=n-1;i>0;i--){yield{type:'swap',i:0,j:i};[arr[0],arr[i]]=[arr[i],arr[0]];yield* heapify(i,0);}for(let i=0;i<n;i++)yield{type:'sorted',i};}function* radixSort(arr){let max=Math.max(...arr);let exp=1;while(Math.floor(max/exp)>0){let output=new Array(arr.length).fill(0);let count=new Array(10).fill(0);for(let i=0;i<arr.length;i++){let digit=Math.floor(arr[i]/exp)%10;count[digit]++;}for(let i=1;i<10;i++)count[i]+=count[i-1];for(let i=arr.length-1;i>=0;i--){let digit=Math.floor(arr[i]/exp)%10;output[count[digit]-1]=arr[i];count[digit]--;}for(let i=0;i<arr.length;i++){if(arr[i]!==output[i]){let j=arr.indexOf(output[i]);yield{type:'swap',i,j};[arr[i],arr[j]]=[arr[j],arr[i]];}}exp*=10;}for(let i=0;i<arr.length;i++)yield{type:'sorted',i};}function createUI(){const container=document.createElement('div');container.style.display='flex';container.style.alignItems='center';container.style.marginTop='10px';const algSelect=document.createElement('select');for(let key in algorithms){let opt=document.createElement('option');opt.value=key;opt.textContent=key;algSelect.appendChild(opt);}algSelect.value=algorithm;algSelect.onchange=()=>{algorithm=algSelect.value;resetState();initData();draw();};container.appendChild(algSelect);const speedLabel=document.createElement('label');speedLabel.textContent=' Speed ';container.appendChild(speedLabel);const speedSlider=document.createElement('input');speedSlider.type='range';speedSlider.min='10';speedSlider.max='200';speedSlider.value=speed;speedSlider.oninput=()=>{speed=parseInt(speedSlider.value);};container.appendChild(speedSlider);const modeLabel=document.createElement('label');modeLabel.textContent=' Continuous ';container.appendChild(modeLabel);const modeChk=document.createElement('input');modeChk.type='checkbox';modeChk.checked=continuous;modeChk.onchange=()=>{continuous=modeChk.checked;document.getElementById('nextBtn').disabled=!continuous;};container.appendChild(modeChk);const nextBtn=document.createElement('button');nextBtn.id='nextBtn';nextBtn.textContent='Next Step';nextBtn.disabled=!continuous;nextBtn.onclick=()=>{if(currentGen){document.getElementById('nextBtn').disabled=true;runGeneratorStep();}};container.appendChild(nextBtn);const scrambleBtn=document.createElement('button');scrambleBtn.textContent='Scramble';scrambleBtn.onclick=()=>{let pattern=prompt('Pattern: Random, Reverse, Nearly','Random');if(pattern)pattern=pattern.toLowerCase();resetState();if(pattern==='reverse')reverse();else if(pattern==='nearly')nearlySorted();else shuffle();draw();};container.appendChild(scrambleBtn);canvas.parentNode.insertBefore(container,canvas.nextSibling);}let currentGen=null;function startSort(){resetState();initData();draw();currentGen=algorithms[algorithm].func(data.slice());runGenerator(currentGen);}function runGeneratorStep(){let res=currentGen.next();if(res.done){sortedSet=new Set([...Array(barCount).keys()]);pivotIdx=null;rangeStart=null;rangeEnd=null;draw();return;}processAction(res.value);draw();if(!continuous)document.getElementById('nextBtn').disabled=false;}createUI();startSort();start();}

